export class EntityProxy {
    /**
     * EntityProxy - Physics Body State Accessor
     *
     * Provides a convenient interface to read physics body state from the
     * SharedArrayBuffer with cached Three.js objects and interpolation support.
     * Use this for rendering physics-driven entities at smooth frame rates.
     *
     * **Features**
     *
     * - Cached THREE.Vector3/Quaternion objects (no allocation per frame)
     * - Interpolation between physics steps for smooth rendering
     * - State flags for game logic (grounded, jumping, moving)
     * - Velocity access for animation blending
     *
     * **Properties Overview**
     *
     * | Property | Type | Description |
     * |----------|------|-------------|
     * | position | Vector3 | Interpolated world position |
     * | quaternion | Quaternion | Interpolated world rotation |
     * | velocity | Vector3 | External velocity (world space) |
     * | localVelocity | Vector3 | Local velocity (body space) |
     * | active | boolean | Whether this slot is in use |
     * | grounded | boolean | Whether touching ground |
     * | jumping | boolean | Currently in jump |
     * | moving | boolean | Has movement input |
     * | sleeping | boolean | Physics sleeping (get/set) |
     * | mass | number | Body mass (get/set) |
     * | friction | number | Body friction (get/set) |
     *
     * ```javascript
     * const player = controller.getDynamic( 0 );
     *
     * // Apply to mesh with interpolation
     * player.interpolate( alpha );
     * mesh.position.copy( player.position );
     * mesh.quaternion.copy( player.quaternion );
     *
     * // Or use the convenience method
     * player.applyTo( mesh, alpha );
     *
     * // Check state for animations
     * if ( player.grounded && player.moving ) {
     *   playWalkAnimation();
     * }
     *
     * // Read velocity for animation speed
     * const speed = player.localVelocity.length();
     * mixer.setEffectiveTimeScale( speed / maxSpeed );
     * ```
     *
     * @class EntityProxy
     * @short Physics body state accessor with interpolation.
     * @category Core
     * @tags Proxy, Interpolation, State
     *
     * @param {BufferBackedObject[]} sharedView - Array of buffer-backed body objects
     * @param {number} index - Index of this body in the array
     * @param {PhysicsController} controller - Parent controller reference
     */
    constructor(sharedView: BufferBackedObject[], index: number, controller: PhysicsController);
    _view: BufferBackedObject[];
    _index: number;
    _controller: PhysicsController;
    position: any;
    quaternion: any;
    velocity: any;
    localVelocity: any;
    _interpolated: {
        position: any;
        quaternion: any;
    };
    /**
     * Get the raw shared buffer view
     */
    get raw(): BufferBackedObject;
    /**
     * Check if this entity slot is in use
     */
    get active(): boolean;
    set sleeping(value: boolean);
    /**
     * Get/set sleep state
     */
    get sleeping(): boolean;
    /**
     * Get grounded state
     */
    get grounded(): boolean;
    /**
     * Get jumping state
     */
    get jumping(): boolean;
    /**
     * Get moving state
     */
    get moving(): boolean;
    set mass(value: any);
    /**
     * Get/set mass
     */
    get mass(): any;
    set friction(value: any);
    /**
     * Get/set friction
     */
    get friction(): any;
    /**
     * Update cached position/quaternion from interpolated values
     * @param {number} alpha - Interpolation factor (0-1)
     */
    interpolate(alpha: number): void;
    /**
     * Apply position/quaternion to a Three.js object
     * @param {THREE.Object3D} object - Object to update
     * @param {number} [alpha=1] - Interpolation factor
     */
    applyTo(object: THREE.Object3D, alpha?: number): void;
    /**
     * Set control input
     * @param {number} x - X axis input (-1 to 1)
     * @param {number} y - Y axis input (-1 to 1)
     */
    setInput(x: number, y: number): void;
    /**
     * Set mouse/look input
     * @param {number} x - X axis rotation
     */
    setMouseInput(x: number): void;
    /**
     * Teleport to position
     * @param {THREE.Vector3|number[]} position - Target position
     */
    teleport(position: THREE.Vector3 | number[]): void;
}
export class PhysicsController {
    /**
     * PhysicsController - Main Thread Physics Orchestrator
     *
     * High-level controller that manages physics entity access, interpolation,
     * and input routing. This is the primary class for integrating physics
     * into your render loop.
     *
     * **Features**
     *
     * - EntityProxy access for reading physics state with interpolation
     * - Automatic input handling from keyboard/gamepad
     * - Frame timing and interpolation alpha calculation
     * - Camera offset control
     *
     * **Key Responsibilities**
     *
     * | Responsibility | Method |
     * |----------------|--------|
     * | Entity access | `getDynamic()`, `getKinematic()` → EntityProxy |
     * | Frame updates | `update()` |
     * | Input routing | `applyInput()` (auto or manual) |
     * | Camera control | `setCameraDrag()`, `setCameraOffsets()` |
     * | Lifecycle | `pause()`, `resume()`, `dispose()` |
     *
     * ```javascript
     * const physics = new Physics();
     * await physics.init();
     * await physics.start();
     *
     * // Input is handled automatically
     * const controller = new PhysicsController( physics );
     *
     * // In render loop
     * function animate() {
     *   controller.update( delta );
     *   renderer.render( scene, camera );
     * }
     * ```
     *
     * @class PhysicsController
     * @short Main thread physics orchestrator with EntityProxy access.
     * @category Core
     * @tags Controller, Update, Input, EntityProxy
     *
     * @param {Physics} physicsAPI - Initialized Physics instance
     * @param {Object} [options={}] - Configuration options
     * @param {boolean} [options.enableInput=true] - Enable automatic input handling
     * @param {number} [options.playerBodyIndex=0] - Body index to apply input to
     * @param {Object} [options.inputOptions={}] - Options to pass to InputController
     */
    constructor(physicsAPI: Physics, options?: {
        enableInput?: boolean;
        playerBodyIndex?: number;
        inputOptions?: any;
    });
    _physics: Physics;
    _dynamicProxies: Map<any, any>;
    _kinematicProxies: Map<any, any>;
    _lastPhysicsTime: number;
    _accumulator: number;
    _updateCallbacks: Set<any>;
    _enableInput: boolean;
    _playerBodyIndex: number;
    _inputController: InputController;
    /**
     * Register playerApi in store with entity reference for helpers like teleportBody.
     * @private
     */
    private _registerPlayerApi;
    /**
     * Toggle pause state (called by InputController on '/' key).
     * @private
     */
    private _togglePause;
    /**
     * Get the underlying Physics
     */
    get api(): Physics;
    /**
     * Get global physics state
     */
    get state(): any;
    /**
     * Get camera state
     */
    get camera(): any;
    /**
     * Check if physics is paused
     */
    get paused(): boolean;
    /**
     * Get the internal InputController instance.
     * Use this to customize input handling or read input state.
     * @returns {InputController|null} The input controller, or null if input is disabled
     */
    get input(): InputController | null;
    /**
     * Enable or disable input processing.
     * When disabled, no input is sent to the player body.
     * Useful for spectator mode, cutscenes, or menus.
     * @param {boolean} enabled - Whether input should be processed
     */
    set inputEnabled(enabled: boolean);
    /**
     * Get whether input processing is enabled.
     * @returns {boolean} True if input is enabled
     */
    get inputEnabled(): boolean;
    /**
     * Pause physics simulation
     */
    pause(): void;
    /**
     * Resume physics simulation
     */
    resume(): void;
    /**
     * Get current physics FPS
     */
    get fps(): any;
    /**
     * Get a dynamic body proxy
     * @param {number} index - Body index
     * @returns {EntityProxy}
     */
    getDynamic(index: number): EntityProxy;
    /**
     * Get a kinematic body proxy
     * @param {number} index - Body index
     * @returns {EntityProxy}
     */
    getKinematic(index: number): EntityProxy;
    /**
     * Get interpolation alpha from Physics class (frame-cached).
     * Delegating to Physics ensures all consumers get identical alpha values
     * within the same frame, preventing timing mismatches.
     *
     * @returns {number} Interpolation factor (0-1)
     */
    getInterpolationAlpha(): number;
    /**
     * Update all entity proxies with interpolation and apply input.
     * Call this in your render loop.
     * @param {number} [delta] - Frame delta (unused, kept for API compatibility)
     */
    update(delta?: number): void;
    /**
     * Register a callback to run each update
     * @param {Function} callback - Function receiving (alpha, delta)
     * @returns {Function} Unsubscribe function
     */
    onUpdate(callback: Function): Function;
    /**
     * Set a property in the temp shared buffer
     * @private
     */
    private _setTemp;
    /**
     * Teleport a body to a position
     * @private
     */
    private _teleport;
    /**
     * Apply input from a gamepad or keyboard
     * @param {number} bodyIndex - Dynamic body index
     * @param {Object} input - Input state
     * @param {number} [input.x=0] - X axis (-1 to 1)
     * @param {number} [input.y=0] - Y axis (-1 to 1)
     * @param {number} [input.look=0] - Look/rotation input
     * @param {boolean} [input.jump=false] - Jump button held state
     */
    applyInput(bodyIndex: number, input: {
        x?: number;
        y?: number;
        look?: number;
        jump?: boolean;
    }): void;
    /**
     * Set camera drag input
     * @param {number} deltaX - X rotation delta
     * @param {number} deltaY - Y rotation delta
     */
    setCameraDrag(deltaX: number, deltaY: number): void;
    /**
     * Set camera offsets
     * @param {Object} offsets
     * @param {THREE.Vector3} [offsets.camera] - Camera offset from target
     * @param {THREE.Vector3} [offsets.target] - Target offset from body
     */
    setCameraOffsets(offsets: {
        camera?: THREE.Vector3;
        target?: THREE.Vector3;
    }): void;
    /**
     * Dispose and clean up
     */
    dispose(): void;
}
export default PhysicsController;
import { InputController } from './InputController.js';
